import { visibleCourses } from "./access.js";
import { academicClassStudents, selectedStudentSubjects, visibleClassNotices, homeworkSubjects, visibleHomework } from "./academic-portal-data.js";
import { avatar, badge, button, emptyState, escapeHtml as e, pageHeading } from "./ui.js";

const footer = (label) => `<p class="form-error" role="alert" hidden></p><footer class="dialog-actions">${button("Cancel", "close-dialog", { variant: "secondary" })}<button class="button primary" type="submit">${label}</button></footer>`;
const options = (subjects, selected) => subjects.map((course) => `<option value="${e(course.id)}" ${course.id === selected ? "selected" : ""}>${e(course.title)} · Class ${e(course.className)}</option>`).join("");

export function classSubjectAssignments({ state, context }) {
  const students = academicClassStudents(state, context), subjects = visibleCourses(state, context);
  return `<section class="surface student-subjects"><header class="panel-heading"><div><h2>Student subjects</h2><p>Choose the subjects each student’s parent can access.</p></div>${badge("Class " + context.grant.className, "green")}</header><div class="student-subject-list">${students.map((student) => `<article>${avatar(student, "small")}<div class="student-subject-name"><strong>${e(student.name)}</strong><span>${e(student.admissionNumber)}</span><div class="subject-pills">${subjects.filter((course) => selectedStudentSubjects(state, student).includes(course.id) && state.assignments[course.id].students.includes(student.id)).map((course) => `<span>${e(course.title)}</span>`).join("") || '<span>No subjects selected</span>'}</div></div>${button("Assign subjects", "academic-assign-subjects", { value: student.id, variant: "secondary", focus: "subjects-" + student.id })}</article>`).join("") || emptyState("users", "No students in this class", "Register students in this class before selecting their subjects.")}</div></section>`;
}
export function studentSubjectsForm({ state, context }, student) {
  const selected = selectedStudentSubjects(state, student), subjects = visibleCourses(state, context);
  return `<form data-form="academic-subjects"><input type="hidden" name="student" value="${e(student.id)}"><div class="form-body"><h3>${e(student.name)}</h3><p>${e(student.admissionNumber)} · Class ${e(student.className)}</p><fieldset class="roster-picker"><legend>Subjects shown to this student’s parent</legend>${subjects.map((course) => `<label class="roster-check"><input type="checkbox" name="subjects" value="${e(course.id)}" ${selected.includes(course.id) ? "checked" : ""}><span><strong>${e(course.title)}</strong> · Class ${e(course.className)}</span></label>`).join("") || "No subjects available for this class."}</fieldset><p>Saving updates this student’s subject enrolment. Teaching appointments stay with school administration.</p></div>${footer("Save student subjects")}</form>`;
}
export function teacherSubjectClasses({ state, context }) {
  const courses = visibleCourses(state, context), titles = [...new Set(courses.map((course) => course.title))];
  return `<section class="subject-class-groups">${titles.map((title) => `<section class="surface subject-class-group"><header class="panel-heading"><div><h2>${e(title)}</h2><p>${courses.filter((course) => course.title === title).length} teaching class(es)</p></div></header><div class="subject-class-grid">${courses.filter((course) => course.title === title).map((course) => `<article><h3>Class ${e(course.className)}</h3><p>${state.assignments[course.id].students.length} students · ${state.materials.filter((material) => material.course === course.id).length} materials</p><div class="academic-actions">${button("Open class", "open-course", { value: course.id, variant: "secondary" })}${button("Give homework", "academic-homework-new", { value: course.id, variant: "secondary" })}</div></article>`).join("")}</div></section>`).join("") || emptyState("book", "No subjects assigned", "School administration can appoint you to subject classes.")}</section>`;
}
export function noticesPage({ state, context, child }) {
  const staff = context.role === "class_teacher", notices = visibleClassNotices(state, context, child);
  return `${pageHeading("Notices", staff ? "Common notices for every parent in your appointed class." : "Notices from your child’s Class Teacher.", staff ? button("New notice", "academic-notice-new", { iconName: "plus" }) : "")}<div class="academic-feed">${notices.map((notice) => {
    const read = state.noticeReads?.[context.account.id + ":" + child?.id + ":" + notice.id] === notice.updatedAt;
    return `<article class="surface academic-feed-card"><header><div>${badge("Class " + notice.className, "green")}${notice.status === "withdrawn" ? badge("Withdrawn", "neutral") : !staff && !read ? badge("New", "amber") : ""}<h2>${e(notice.title)}</h2></div><time>${e(notice.updatedAt.slice(0, 10))}</time></header><p class="academic-message">${e(notice.message)}</p><footer><span>${e(notice.by)} · Class Teacher</span>${staff ? button("Edit notice", "academic-notice-edit", { value: notice.id, variant: "secondary" }) : button(read ? "Read" : "Mark as read", "academic-notice-read", { value: notice.id, variant: read ? "completed" : "secondary", extra: read ? "disabled" : "" })}</footer></article>`;
  }).join("") || `<section class="surface">${emptyState("file", "No class notices", staff ? "Publish a notice to make it visible to all parents in this class." : "New notices from the Class Teacher will appear here.")}</section>`}</div>`;
}
export function noticeForm(notice = {}) {
  return `<form data-form="academic-notice"><input type="hidden" name="id" value="${e(notice.id || "")}"><div class="form-body"><label class="field">Notice title<input name="title" maxlength="120" required value="${e(notice.title || "")}"></label><label class="field">Message<textarea name="message" rows="6" maxlength="2000" required>${e(notice.message || "")}</textarea></label>${notice.id ? `<label class="field">Visibility<select name="status"><option value="published" ${notice.status === "published" ? "selected" : ""}>Published to class parents</option><option value="withdrawn" ${notice.status === "withdrawn" ? "selected" : ""}>Withdrawn</option></select></label>` : ""}<p>Visible in the parent portal for every student in your class.</p></div>${footer(notice.id ? "Save notice" : "Publish notice")}</form>`;
}
export function homeworkPage({ state, context, child, academicSubject }) {
  const staff = context.role !== "parent", subjects = homeworkSubjects(state, context, child), selected = subjects.some((course) => course.id === academicSubject) ? academicSubject : "all", items = visibleHomework(state, context, child).filter((item) => selected === "all" || item.course === selected);
  return `${pageHeading("Homework", staff ? "Give and manage homework separately for each subject and class." : "Homework for your child’s assigned subjects.", staff && subjects.length ? button("Give homework", "academic-homework-new", { value: selected === "all" ? "" : selected, iconName: "plus" }) : "")}<div class="academic-filter"><label class="field">Subject and class<select data-change="academic-subject"><option value="all">All assigned subjects</option>${options(subjects, selected)}</select></label></div><div class="academic-feed">${items.map((item) => {
    const subject = subjects.find((course) => course.id === item.course), done = state.homeworkCompleted?.[child?.id]?.[item.id];
    return `<article class="surface academic-feed-card"><header><div><div class="subject-pills"><span>${e(subject.title)}</span><span>Class ${e(item.className)}</span>${item.status === "withdrawn" ? badge("Withdrawn", "neutral") : ""}</div><h2>${e(item.title)}</h2></div><span class="homework-due">Due ${e(item.due)}</span></header><p class="academic-message">${e(item.instructions)}</p><footer><span>Given by ${e(item.by)}</span><div class="academic-actions">${button("Download homework", "academic-homework-download", { value: item.id, variant: "secondary", iconName: "download" })}${staff ? button("Edit homework", "academic-homework-edit", { value: item.id, variant: "secondary" }) : button(done ? "Done" : "Mark done", "academic-homework-done", { value: item.id, variant: done ? "completed" : "primary", iconName: done ? "check" : "circleDot", extra: `aria-pressed="${Boolean(done)}"` })}</div></footer></article>`;
  }).join("") || `<section class="surface">${emptyState("book", "No homework in this selection", staff ? "Choose a subject and class, then give homework." : "Homework from your Class Teacher or Subject Teacher will appear here.")}</section>`}</div>`;
}
export function homeworkForm({ state, context }, item = {}, selected = "") {
  const subjects = homeworkSubjects(state, context);
  return `<form data-form="academic-homework"><input type="hidden" name="id" value="${e(item.id || "")}"><div class="form-body"><label class="field">Subject and class<select name="course" required ${item.id ? "disabled" : ""}>${options(subjects, item.course || selected)}</select></label>${item.id ? `<input type="hidden" name="course" value="${e(item.course)}">` : ""}<label class="field">Homework title<input name="title" maxlength="120" required value="${e(item.title || "")}"></label><label class="field">Instructions<textarea name="instructions" rows="5" maxlength="3000" required>${e(item.instructions || "")}</textarea></label><label class="field">Due date<input name="due" type="date" required value="${e(item.due || "2026-11-25")}"></label>${item.id ? `<label class="field">Visibility<select name="status"><option value="published" ${item.status === "published" ? "selected" : ""}>Published</option><option value="withdrawn" ${item.status === "withdrawn" ? "selected" : ""}>Withdrawn</option></select></label>` : ""}</div>${footer(item.id ? "Save homework" : "Publish homework")}</form>`;
}
